from pathlib import Path
p=Path('/home/lowkanta/meuharness/src/meuharness/web_assets/index.html')
s=p.read_text()
start=s.index('async function renderEvents(){')
end=s.index('async function renderApprovals(){', start)
new=r'''let eventViewState={query:'',type:'all',agent:'all',errorsOnly:false};
function eventStatus(t=''){t=String(t).toLowerCase();if(/failed|error|denied/.test(t))return'bad';if(/completed|approved|success/.test(t))return'ok';if(/started|running/.test(t))return'running';return'neutral'}
function eventShort(v=''){v=String(v||'');return v.length>18?v.slice(0,8)+'…'+v.slice(-6):v}
function eventTime(v=''){try{return new Date(v).toLocaleString('pt-BR')}catch(_){return String(v||'')}}
function renderEventRows(ev){const h=document.querySelector('#eventsRows');if(!h)return;const q=eventViewState.query.toLowerCase(),list=ev.filter(e=>{const hay=[e.type,e.agent_id,e.run_id,e.scope,e.created_at].join(' ').toLowerCase();return(!q||hay.includes(q))&&(eventViewState.type==='all'||e.type===eventViewState.type)&&(eventViewState.agent==='all'||e.agent_id===eventViewState.agent)&&(!eventViewState.errorsOnly||eventStatus(e.type)==='bad')});h.innerHTML=list.map(e=>`<div class="event-row ${eventStatus(e.type)}"><div class="event-state"><i></i></div><div class="event-main"><div class="event-title-line"><b>${esc(e.type||'event')}</b><span>${esc(eventTime(e.created_at))}</span></div><div class="event-details">${e.agent_id?`<span>agente <strong>${esc(e.agent_id)}</strong></span>`:''}${e.run_id?`<span>run <code title="${esc(e.run_id)}">${esc(eventShort(e.run_id))}</code></span>`:''}${e.scope?`<span>scope <code>${esc(e.scope)}</code></span>`:''}${!e.agent_id&&!e.run_id&&!e.scope?'<span class="muted">evento do sistema</span>':''}</div></div></div>`).join('')||'<div class="events-empty">Nenhum evento corresponde aos filtros.</div>';document.querySelector('#eventsVisibleCount').textContent=list.length+' visíveis'}
async function renderEvents(){stopWorld();stopOpsTimer();currentView='events';selected=null;title.textContent='Eventos';let first=true;const paint=async()=>{try{const j=await api('/api/events?limit=120'),ev=j.events||[],types=[...new Set(ev.map(e=>e.type).filter(Boolean))].sort(),ids=[...new Set(ev.map(e=>e.agent_id).filter(Boolean))].sort(),bad=ev.filter(e=>eventStatus(e.type)==='bad').length,run=ev.filter(e=>eventStatus(e.type)==='running').length,ok=ev.filter(e=>eventStatus(e.type)==='ok').length;if(first||!document.querySelector('#eventsRows')){content.innerHTML=`<div class="events-page"><div class="events-head"><div><h1>Eventos</h1><p>Telemetria operacional do kernel, scheduler, automações, approvals e Computer Use.</p></div><span class="telemetry-live">LIVE · ${ev.length}</span></div><div class="events-summary"><div><span>Total</span><b>${ev.length}</b></div><div class="ok"><span>Concluídos</span><b>${ok}</b></div><div class="running"><span>Iniciados</span><b>${run}</b></div><div class="bad"><span>Falhas</span><b>${bad}</b></div></div><div class="events-toolbar"><input id="eventsSearch" placeholder="Buscar evento, agente ou run..."><select id="eventsType"><option value="all">Todos os eventos</option>${types.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select><select id="eventsAgent"><option value="all">Todos os agentes</option>${ids.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select><label class="events-errors-only"><input type="checkbox" id="eventsErrorsOnly"> só falhas</label><span id="eventsVisibleCount"></span></div><section class="events-feed"><div class="events-feed-head"><span>Status</span><span>Evento / detalhes</span></div><div id="eventsRows"></div></section></div>`;document.querySelector('#eventsSearch').oninput=e=>{eventViewState.query=e.target.value;renderEventRows(ev)};document.querySelector('#eventsType').onchange=e=>{eventViewState.type=e.target.value;renderEventRows(ev)};document.querySelector('#eventsAgent').onchange=e=>{eventViewState.agent=e.target.value;renderEventRows(ev)};document.querySelector('#eventsErrorsOnly').onchange=e=>{eventViewState.errorsOnly=e.target.checked;renderEventRows(ev)};first=false}else{document.querySelector('.events-head .telemetry-live').textContent='LIVE · '+ev.length;const b=document.querySelectorAll('.events-summary b');[ev.length,ok,run,bad].forEach((v,i)=>b[i].textContent=v)}renderEventRows(ev)}catch(e){content.innerHTML=`<div class="empty">${esc(e.message)}</div>`}};await paint();opsTimer=setInterval(paint,2000)}
'''
s=s[:start]+new+s[end:]
css=r'''
/* EVENTS CONSOLE */
.events-page{max-width:1500px;margin:0 auto 50px}.events-head{display:flex;align-items:flex-end;gap:16px;margin-bottom:12px}.events-head>div{flex:1}.events-head h1{margin:0 0 4px;font-size:20px}.events-head p{margin:0;color:#687487;font-size:11px}.events-summary{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid #202631;background:#090b0e;margin-bottom:10px}.events-summary>div{padding:10px 12px;border-right:1px solid #202631}.events-summary>div:last-child{border-right:0}.events-summary span{display:block;font-size:8px;text-transform:uppercase;letter-spacing:.08em;color:#566174}.events-summary b{display:block;margin-top:3px;font-size:16px}.events-summary .ok b{color:#9ece6a}.events-summary .running b{color:#7aa2f7}.events-summary .bad b{color:#f7768e}.events-toolbar{display:grid;grid-template-columns:minmax(260px,1fr) 220px 200px auto auto;gap:7px;align-items:center;margin-bottom:9px}.events-toolbar input,.events-toolbar select{height:34px!important;padding:6px 9px!important;font-size:10px!important;background:#080b0f!important}.events-errors-only{height:34px;display:flex;align-items:center;gap:7px;border:1px solid #272e38;background:#0a0d11;padding:0 9px;color:#8894a6;font-size:9px;white-space:nowrap}.events-errors-only input{width:auto!important;height:auto!important}.events-toolbar #eventsVisibleCount{font-size:9px;color:#566174;text-align:right;white-space:nowrap}.events-feed{border:1px solid #202631;background:#080a0d}.events-feed-head{display:grid;grid-template-columns:42px 1fr;gap:8px;min-height:30px;align-items:center;padding:0 10px;border-bottom:1px solid #202631;background:#0c0f13;color:#526073;font-size:8px;text-transform:uppercase;letter-spacing:.07em}.event-row{display:grid;grid-template-columns:42px 1fr;gap:8px;min-height:62px;padding:8px 10px;border-bottom:1px solid #171c23}.event-row:hover{background:#0c1015}.event-state{display:grid;place-items:start center;padding-top:7px;position:relative}.event-state:after{content:'';position:absolute;top:18px;bottom:-17px;width:1px;background:#1d2631}.event-row:last-child .event-state:after{display:none}.event-state i{width:8px;height:8px;background:#667286;box-shadow:0 0 0 3px #11161d;z-index:1}.event-row.ok .event-state i{background:#9ece6a}.event-row.running .event-state i{background:#7aa2f7}.event-row.bad .event-state i{background:#f7768e}.event-title-line{display:flex;gap:10px;align-items:center}.event-title-line b{font-size:11px;color:#d2dbe7}.event-row.ok .event-title-line b{color:#b8d9a5}.event-row.running .event-title-line b{color:#9bbcf8}.event-row.bad .event-title-line b{color:#f4a0ae}.event-title-line>span{margin-left:auto;font-size:9px;color:#536074}.event-details{display:flex;gap:14px;flex-wrap:wrap;margin-top:6px;font-size:9px;color:#657184}.event-details strong{color:#aeb8c6}.event-details code{font-size:9px;color:#8fa7c8;background:#090d12;border:1px solid #202a36;padding:2px 5px}.events-empty{padding:42px;text-align:center;color:#5e697b;font-size:10px}@media(max-width:1000px){.events-toolbar{grid-template-columns:1fr 1fr}.events-summary{grid-template-columns:1fr 1fr}}@media(max-width:650px){.events-toolbar{grid-template-columns:1fr}.event-title-line{align-items:flex-start;flex-direction:column}.event-title-line>span{margin-left:0}}
/* /EVENTS CONSOLE */
'''
s=s.replace('</style></head>',css+'</style></head>',1)
p.write_text(s)
print('patched',p)
